<div class="be_page"><div class="be_pagehead"><h1><?= e(t('rev.add')) ?> <span class="muted">#<?= (int)$sub['id'] ?></span></h1></div><div class="be_card">
<form class="be_filters" method="get" action="<?= e(url('review', 'search', [$sub['id']])) ?>"><input type="search" name="q" value="<?= e($q) ?>" placeholder="<?= e(t('rev.search_ph')) ?>" aria-label="<?= e(t('rev.search_ph')) ?>"><button class="be_btn" type="submit"><?= e(t('dash.filter')) ?></button></form>
<table class="be_table"><thead><tr><th><?= e(t('users.name')) ?></th><th><?= e(t('rev.interests')) ?></th><th><?= e(t('rev.active')) ?></th><th><?= e(t('rev.last')) ?></th><th><?= e(t('rev.avg')) ?></th><th></th></tr></thead><tbody>
<?php foreach ($results as $r): ?><tr><td><?= e(trim($r['given_name'] . ' ' . $r['family_name'])) ?><div class="muted be_small"><?= e($r['affiliation']) ?></div></td><td><?= e($r['reviewing_interests'] ?: '-') ?></td><td><?= (int)$r['active_reviews'] ?></td><td><?= e($r['last_completed'] ? fmt_date($r['last_completed']) : '-') ?></td><td><?= $r['avg_days'] !== null ? e($r['avg_days']) : '-' ?></td>
<td class="be_actions"><?php if (in_array((int)$r['id'], $taken, true)): ?><span class="muted"><?= e(t('rev.already_short')) ?></span><?php else: ?><a class="be_btn be_btn_primary" href="<?= e(url('review', 'add', [$sub['id'], $r['id']])) ?>"><?= e(t('rev.select')) ?></a><?php endif; ?></td></tr><?php endforeach; ?>
